def solve() -> int:
    price_per_can = 4.5
    discount = 0.1
    total_price = price_per_can * 2
    if total_price > 2:
        discount_amount = total_price * discount
    else:
        discount_amount = total_price - discount_amount
    result = discount_amount
    return result

